import re,os,json,html
from urllib.parse import unquote
D='site'
files=os.listdir(D)
red={};pg={}
for f in files:
    s=open(os.path.join(D,f),encoding='utf-8').read()
    r=re.search(r'http-equiv="refresh"[^>]*url=([^"]+)"',s)
    if r: red[f]=unquote(r.group(1));continue
    m=re.search(r'<main>(.*?)</main>',s,re.S)
    if f in('index.html','sobre.html','contato.html') or not m: continue
    h=html.unescape(re.search(r'<h1>(.*?)</h1>',m.group(1)).group(1)).strip().lower()
    t=re.search(r'class="tema">Tema: (.*?)<',m.group(1))
    L=[(sid,unquote(h2)) for sid,b in re.findall(r'<section id="(\w+)">(.*?)</section>',m.group(1),re.S) for h2 in re.findall(r'<a href="([^"]+)"',b)]
    pg[f]=(h,t.group(1).lower() if t else '',L)
def res(h):
    h=red.get(h,h); return h if h in pg else None
adj={pg[f][0]:set() for f in pg}
kind={}
for f,(w,t,L) in pg.items():
    for sid,h in L:
        g=res(h)
        if not g: continue
        v=pg[g][0]
        if v==w: continue
        adj[w].add(v);adj[v].add(w)
        kind.setdefault(tuple(sorted((w,v))),set()).add(sid)
words={w:sorted(a) for w,a in sorted(adj.items())}
theme={pg[f][0]:pg[f][1] for f in pg}
pairs=len(kind)
mx=max(len(a) for a in adj.values())
top=sorted(w for w,a in adj.items() if len(a)==mx)
json.dump(words,open('words.json','w',encoding='utf-8'),ensure_ascii=False,indent=1)
json.dump({'words':len(words),'relations':pairs,'most_connected':top[0]},open('result.json','w',encoding='utf-8'),ensure_ascii=False)
print(len(words),pairs,mx,top,sum(1 for a in adj.values() if not a))
syn=[[a,b] for (a,b),k in kind.items() if 'sinonimos' in k]
G={'n':{w:{'t':theme[w],'l':words[w]} for w in words},'s':syn}
open('tmp/G.json','w',encoding='utf-8').write(json.dumps(G,ensure_ascii=False,separators=(',',':')))


